    def import_task_estimations_from_csv_file(
        self,
        project_id: str,
        task_type_id: str,
        *,
        file: FileInput,
        extra_body: Optional[Mapping[str, Any]] = None,
    ) -> list[Optional[dict[str, Any]]]:
        """Import task estimations from a CSV file.

        Set the estimations, the dates and the other values of the tasks of a task type
        from a CSV file. Each line gives one entity. The columns are Parent, Entity,
        Estimation, Drawings, Start date, Due date, Difficulty and the names of the task
        metadata descriptors of the task type. For an asset task type, Parent is the
        asset type and Entity is the asset. For a shot task type, Parent is the sequence
        and Entity is the shot. For a sequence or an edit task type, Parent is the name
        of its episode, or empty to match any episode, and Entity is the sequence or the
        edit. For an episode task type, Entity is the episode and the route ignores
        Parent. When several entities match a line, the ones with the exact name win,
        then the ones that are not canceled. If a line still matches several entities,
        the route refuses it. The route does not support concept task types. The
        Estimation column is in hours when the organisation shows durations in hours, in
        days otherwise. Dates use the YYYY-MM-DD format. If Due date is empty and Start
        date and Estimation are set, the route computes the due date from them. Send the
        CSV file in a multipart form. The route finds the separator of the file. Each
        line is imported in order. If a line is not valid, the import stops. You must be
        an administrator, a manager of the project, or a supervisor of the project. A
        supervisor must have no department, or the department of the task type must be
        one of their departments.

        Args:
            project_id: Unique identifier of the project
            task_type_id: Unique identifier of the task type
            file: CSV file with task estimation data

        ``POST /import/csv/projects/{project_id}/task-types/{task_type_id}/estimations``
        """
        return self._t.request(
            "POST",
            "/import/csv/projects/{project_id}/task-types/{task_type_id}/estimations",
            path_params={"project_id": project_id, "task_type_id": task_type_id},
            body={},
            extra_body=extra_body,
            files={"file": file},
            body_mode="multipart",
            response_type=list[Optional[dict[str, Any]]],
        )

    def import_task_estimations_of_episode_from_csv_file(
        self,
        project_id: str,
        episode_id: str,
        task_type_id: str,
        *,
        file: FileInput,
        extra_body: Optional[Mapping[str, Any]] = None,
    ) -> list[Optional[dict[str, Any]]]:
        """Import task estimations of an episode from a CSV file.

        Set the estimations, the dates and the other values of the tasks of a task type
        from a CSV file. Each line gives one entity. The columns are Parent, Entity,
        Estimation, Drawings, Start date, Due date, Difficulty and the names of the task
        metadata descriptors of the task type. The route changes only the tasks of the
        episode. Use main for the entities without episode and all for every entity of
        the project. For an asset task type, Parent is the asset type and Entity is the
        asset, among the assets of the episode and the ones cast into it. For a shot
        task type, Parent is the sequence and Entity is the shot, among the shots of the
        episode. For a sequence or an edit task type, Entity is the sequence or the
        edit, among the ones of the episode. Parent is empty or the name of the episode.
        With main, Parent is empty. With all, Parent names the episode, or is empty to
        match any episode. For an episode task type, Entity is the episode, and the
        route ignores Parent and the episode of the route. When several entities match a
        line, the ones with the exact name win, then the ones that are not canceled,
        then the assets of the episode over the ones cast into it. If a line still
        matches several entities, the route refuses it. The route does not support
        concept task types. The Estimation column is in hours when the organisation
        shows durations in hours, in days otherwise. Dates use the YYYY-MM-DD format. If
        Due date is empty and Start date and Estimation are set, the route computes the
        due date from them. Send the CSV file in a multipart form. The route finds the
        separator of the file. Each line is imported in order. If a line is not valid,
        the import stops. You must be an administrator, a manager of the project, or a
        supervisor of the project. A supervisor must have no department, or the
        department of the task type must be one of their departments.

        Args:
            project_id: Unique identifier of the project
            episode_id: Unique identifier of the episode, or main, or all. Another value
                gives a 400.
            task_type_id: Unique identifier of the task type
            file: CSV file with task estimation data

        ``POST /import/csv/projects/{project_id}/episodes/{episode_id}/task-types/{task_type_id}/estimations``
        """
        return self._t.request(
            "POST",
            "/import/csv/projects/{project_id}/episodes/{episode_id}/task-types/{task_type_id}/estimations",
            path_params={"project_id": project_id, "episode_id": episode_id, "task_type_id": task_type_id},
            body={},
            extra_body=extra_body,
            files={"file": file},
            body_mode="multipart",
            response_type=list[Optional[dict[str, Any]]],
        )

